/** Functional Ozi coverage inside existing offlineformats, no independent test queue. */
final class OziChecks {
 final MapAndroidChecks m;final GeoTiffChecks shared;OziChecks(MapAndroidChecks m){this.m=m;shared=new GeoTiffChecks(m);}
 int convert(File map,File image,File target,boolean cancel)throws Exception{Class<?> p=m.owned("CacheExport$Progress");Object callback=Proxy.newProxyInstance(p.getClassLoader(),new Class[]{p},(o,method,args)->{if(method.getName().equals("update")&&cancel&&(Integer)args[0]>0)throw new IOException("QA_CANCEL");return null;});return (Integer)m.staticCall("OziImport","write",new Class[]{File.class,File.class,String.class,File.class,p},map,image,image.getName(),target,callback);}
 Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
 void write(File file,String text)throws Exception{shared.put(file,text.getBytes("UTF-8"));}
 void image(File file,int width,int height,boolean jpeg)throws Exception{Bitmap bitmap=Bitmap.createBitmap(width,height,Bitmap.Config.ARGB_8888);try{bitmap.eraseColor(jpeg?0xff808080:0xff5080b0);if(!jpeg){bitmap.setPixel(0,0,0);bitmap.setPixel(1,1,0xff463c64);bitmap.setPixel(16,16,0xff349464);bitmap.setPixel(17,17,0xff66bc64);bitmap.setPixel(width-1,height-1,0xffb81464);bitmap.setPixel(2,2,0x80786464);}try(FileOutputStream out=new FileOutputStream(file)){m.check(bitmap.compress(jpeg?Bitmap.CompressFormat.JPEG:Bitmap.CompressFormat.PNG,100,out),"synthetic Ozi image encoded");}}finally{bitmap.recycle();}}
 void run()throws Exception{File dir=m.getTargetContext().getFilesDir(),map=new File(dir,"qa_ozi.map"),image=new File(dir,"qa_ozi.png"),target=new File(dir,"qa_ozi.mbtiles");int requests=m.requests.get();try{
  image(image,35,33,false);byte[] originalImage=GeoTiffChecks.read(image);for(double[] matrix:new double[][]{{.01,.004,2,.002,-.01,1},{0,-.01,2,-.01,0,1}}){String text=OziFixtures.map(image.getName(),35,33,matrix);write(map,text);m.check(convert(map,image,target,false)>0,"Ozi imports explicit affine image pair into ordinary MBTiles");for(int[] p:new int[][]{{1,1,0xff463c64},{16,16,0xff349464},{17,17,0xff66bc64},{34,32,0xffb81464},{0,0,0}}){double x=p[0]+.5,y=p[1]+.5;shared.worldPixel(target,matrix[0]*x+matrix[1]*y+matrix[2],matrix[3]*x+matrix[4]*y+matrix[5],p[2]);}if(matrix[0]!=0)shared.worldPixel(target,2.001,.671,0);try(SQLiteDatabase db=SQLiteDatabase.openDatabase(target.getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor cursor=db.rawQuery("SELECT name,value FROM metadata WHERE name IN ('bounds','maxzoom') ORDER BY name",null)){m.check(cursor.moveToFirst(),"Ozi converted bounds present");String[] actual=cursor.getString(1).split(",");double[] want=matrix[0]!=0?new double[]{2,.67,2.482,1.07}:new double[]{1.67,.65,2,1};m.check(actual.length==4,"Ozi bounds has four coordinates");for(int i=0;i<4;i++)m.check(Math.abs(Double.parseDouble(actual[i])-want[i])<1e-10,"Ozi geographic bounds matches literal controls");m.check(cursor.moveToNext()&&cursor.getInt(1)==8,"Ozi native resolution follows affine pixel step");}m.check(Arrays.equals(originalImage,GeoTiffChecks.read(image))&&text.equals(new String(GeoTiffChecks.read(map),"UTF-8")),"Ozi conversion preserves both input files exact");byte[] prior=GeoTiffChecks.read(target);boolean refused=false;try{convert(map,image,target,true);}catch(InvocationTargetException e){refused=e.getCause() instanceof IOException;}m.check(refused&&Arrays.equals(prior,GeoTiffChecks.read(target)),"Ozi cancellation retains previous map exact");}
  String good=OziFixtures.map(image.getName(),35,33,new double[]{.01,.004,2,.002,-.01,1});byte[] prior=GeoTiffChecks.read(target);for(String invalid:new String[]{good.replace("WGS 84","Pulkovo 1942"),good.replace("MSF,1","MSF,2"),good.replace("Latitude/Longitude","Mercator"),good.replace("PolyCal,No","PolyCal,Yes"),good.replace("AutoCalOnly,No","AutoCalOnly,Yes"),good.replace("BSBUseWPX,No","BSBUseWPX,Yes"),good.replace(image.getName(),"other.png"),good.replace(image.getName(),"../"+image.getName()),good.replace("35,33","36,33"),good+OziFixtures.point(5,17,17,2.5,.7),good+"MMPNUM,4\nMMPXY,1,0,0\nMMPXY,2,34,0\nMMPXY,3,34,32\nMMPXY,4,0,32\n"}){write(map,invalid);boolean refused=false;try{convert(map,image,target,false);}catch(InvocationTargetException e){refused=e.getCause() instanceof IOException;}m.check(refused&&Arrays.equals(prior,GeoTiffChecks.read(target)),"unsupported Ozi calibration refuses without touching old map");m.check(invalid.equals(new String(GeoTiffChecks.read(map),"UTF-8"))&&Arrays.equals(originalImage,GeoTiffChecks.read(image)),"Ozi refusal preserves both inputs exact");}
  image(image,35,33,true);write(map,good);m.check(convert(map,image,target,false)>0,"JPEG signature is decoded explicitly regardless of picked extension");shared.worldPixel(target,2.245,.835,0xff808080);
  image(image,2560,1792,false);write(map,OziFixtures.map(image.getName(),2560,1792,new double[]{.0001,0,2,0,-.0001,1}));Object raster=m.owned("OziRaster").getConstructor(File.class,File.class,String.class).newInstance(map,image,image.getName());try{for(int y=0;y<7;y++)for(int x=0;x<10;x++)m.check((Integer)m.call(raster,"color",new Class[]{double.class,double.class},2+(x*256+100.5)*.0001,1-(y*256+100.5)*.0001)==0xff5080b0,"regional Ozi decode accesses independent source tile");Map<?,?> cache=(Map<?,?>)field(raster,"tiles");m.check(cache.size()==64&&((Long)field(raster,"bytes"))<=16L*1024*1024,"Ozi region LRU evicts at strict 64 blocks /16MiB");}finally{m.call(raster,"close",new Class[]{});}boolean closed=false;try{m.call(raster,"color",new Class[]{double.class,double.class},2.01,.99);}catch(InvocationTargetException e){closed=e.getCause() instanceof IOException;}m.check(closed,"closed Ozi reader cannot decode recycled regions");
  ui(map,image);m.check(m.requests.get()==requests,"Ozi reads only explicit local pair and makes no tile requests");
 }finally{map.delete();image.delete();target.delete();}}
 void prompt(ManagerVisualChecks visual)throws Exception{m.waitForIdleSync();final Throwable[] error={null};m.runOnMainSync(()->{try{android.view.View root=m.activeDialogRoot();JSONArray texts=new JSONArray();visual.inspect(root,texts);for(int i=0;i<texts.length();i++){JSONObject text=texts.getJSONObject(i);if(text.getBoolean("visible"))m.check(text.getBoolean("arimo"),"Ozi visible dialog text uses Arimo");}android.view.View apply=visual.button(root,"Импортировать"),cancel=visual.button(root,"Отмена");m.check(apply!=null&&cancel!=null&&visual.fullyVisible(apply)&&visual.fullyVisible(cancel),"Ozi explicit import and Cancel fully reachable");visual.emit("OZI_PROMPT "+texts.toString());}catch(Throwable e){error[0]=e;}});if(error[0]!=null)throw new AssertionError(error[0]);}
 void stale(File map,File image,File local,byte[] previous)throws Exception{ExecutorService worker=(ExecutorService)field(m.activity,"worker");CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);worker.execute(()->{entered.countDown();try{release.await(30,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});m.check(entered.await(5,TimeUnit.SECONDS),"Ozi owner worker paused before conversion");try{selected(map,image);m.click("Импортировать");File replacement=File.createTempFile("qa-ozi-other-window-",".mbtiles",local.getParentFile());try{shared.put(replacement,previous);m.check(replacement.renameTo(local),"other window replaces map inode before Ozi install");}finally{replacement.delete();}}finally{release.countDown();}m.waitText("Карта не заменена");m.check(Arrays.equals(previous,GeoTiffChecks.read(local)),"stale Ozi installer cannot overwrite replacement map");}
 void pick(File map,File image)throws Exception{ClipData data=ClipData.newRawUri("synthetic Ozi",Uri.fromFile(image));data.addItem(new ClipData.Item(Uri.fromFile(map)));Intent result=new Intent();result.setClipData(data);IntentFilter filter=new IntentFilter(Intent.ACTION_OPEN_DOCUMENT);filter.addCategory(Intent.CATEGORY_OPENABLE);filter.addDataType("*/*");Instrumentation.ActivityMonitor monitor=m.addMonitor(filter,new Instrumentation.ActivityResult(Activity.RESULT_OK,result),true);try{m.click("Карты");m.click("Подложка");m.click("Импорт Ozi (.map + PNG/JPEG)");m.waitText("Импортировать");m.check(monitor.getHits()==1,"real map menu launches document picker; synthetic explicit pair returned");}finally{m.removeMonitor(monitor);}}
 void selected(File map,File image)throws Exception{Throwable[] failure={null};m.runOnMainSync(()->{try{ClipData data=ClipData.newRawUri("synthetic Ozi",Uri.fromFile(image));data.addItem(new ClipData.Item(Uri.fromFile(map)));Intent intent=new Intent();intent.setClipData(data);Method method=m.activity.getClass().getDeclaredMethod("onActivityResult",int.class,int.class,Intent.class);method.setAccessible(true);method.invoke(m.activity,4303,Activity.RESULT_OK,intent);}catch(Throwable e){failure[0]=e;}});if(failure[0]!=null)throw new AssertionError(failure[0]);m.waitText("Импорт Ozi");}
 void ui(File map,File image)throws Exception{Context c=m.getTargetContext();Object store=m.storeClass.getConstructor(Context.class).newInstance(c);long project=-1,other=-1;ManagerRotationChecks raw=new ManagerRotationChecks(m);MapLayersChecks layers=new MapLayersChecks(m);ManagerVisualChecks visual=new ManagerVisualChecks(m);try{project=new GeometryConfirmationChecks(m).fixture(store,false);other=new GeometryConfirmationChecks(m).fixture(store,false);byte[] xml=raw.xml(raw.load(store,project)),otherXml=raw.xml(raw.load(store,other));Map<String,byte[]> assets=new HashMap<>(m.assets(raw.load(store,project))),otherAssets=new HashMap<>(m.assets(raw.load(store,other)));File local=new File(c.getFilesDir(),"local_basemap_"+project+".mbtiles"),foreign=new File(c.getFilesDir(),"local_basemap_"+other+".mbtiles");shared.put(foreign,new byte[]{71,72,73});byte[] foreignBytes=GeoTiffChecks.read(foreign);image(image,35,33,false);String calibration=OziFixtures.map(image.getName(),35,33,new double[]{.01,.004,2,.002,-.01,1});write(map,calibration);byte[] imageBytes=GeoTiffChecks.read(image);layers.main(project);pick(map,image);m.capture("mvisual-ozi-import-prompt");prompt(visual);m.click("Отмена");m.check(!local.exists(),"Ozi explicit Cancel installs no private map");layers.unchanged(store,project,xml,assets);layers.unchanged(store,other,otherXml,otherAssets);selected(map,image);m.click("Импортировать");m.waitText("Локальная карта MBTiles");m.check(local.isFile(),"Ozi explicit UI import installs valid existing map format");shared.worldPixel(local,2.021,.988,0xff463c64);m.capture("mvisual-ozi-import-saved");byte[] before=GeoTiffChecks.read(local);selected(map,image);m.click("Отмена");m.check(Arrays.equals(before,GeoTiffChecks.read(local)),"Cancel retains exact previous private map");stale(map,image,local,before);visual.finish();layers.main(project);m.waitText("Локальная карта MBTiles");shared.worldPixel(local,2.021,.988,0xff463c64);m.check(Arrays.equals(before,GeoTiffChecks.read(local)),"Ozi converted map reopens without rewriting");m.check(Arrays.equals(imageBytes,GeoTiffChecks.read(image))&&calibration.equals(new String(GeoTiffChecks.read(map),"UTF-8")),"UI leaves explicit source pair exact");m.check(Arrays.equals(foreignBytes,GeoTiffChecks.read(foreign)),"Ozi import/Cancel/reopen preserves other project map exact");layers.unchanged(store,project,xml,assets);layers.unchanged(store,other,otherXml,otherAssets);
 }finally{visual.finish();for(long id:new long[]{project,other})if(id>0){m.call(store,"remove",new Class[]{long.class},id);m.staticCall("LocalMapActivity","cleanupDeletedProject",new Class[]{Context.class,long.class},c,id);}m.call(store,"close",new Class[]{});}}
}
